{
  "verdict": "request_changes",
  "summary": "Candidate implementation fails to preserve original order for tickets with equal priority, violating the stability requirement of the contract.",
  "findings": [
    {
      "finding_id": "F001",
      "file": "candidate.py",
      "line_start": 2,
      "line_end": 2,
      "severity": "high",
      "description": "Reversing the sorted list breaks the required stable ordering for tickets with equal priority.",
      "evidence": "For input [(\"t1\", 5), (\"t2\", 5), (\"t3\", 3)], candidate.queue_order returns [\"t2\", \"t1\", \"t3\"], but the specification requires the output to be [\"t1\", \"t2\", \"t3\"]. The current implementation uses sorted(...)[::-1], which reverses the entire list, thus reversing the relative order of equal‑priority tickets."
    }
  ]
